'use client';
import {useEffect,useMemo,useState} from 'react';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import toast from 'react-hot-toast';
import {
 addSyllabusTopic,changeSyllabusScope,changeSyllabusStatus,commitFrameworkImport,deleteSyllabusDocument,discoverOfficialSyllabusDocuments,getFrameworkCoverage,getSyllabusDetail,getSyllabusDocument,getSyllabusDocuments,getSyllabusOptions,getSyllabusSources,importSyllabusDocument,previewFrameworkImport,retireSyllabusTopic,reviewSyllabusDocument,updateSyllabusDocument,updateSyllabusTopic,uploadSyllabusDocuments,
 type FrameworkImportRow,type OfficialSyllabusDocument,type SyllabusDocument,type SyllabusTopic
} from '@/services/syllabusService';

type Tab='library'|'import'|'review';
const headers=['board_code','medium','academic_year','class_code','subject_code','unit','chapter','topic','topic_hi','learning_outcome','source_url','page_reference','sort_order'];
const message=(error:unknown)=>{const value=error as {response?:{data?:{error?:{message?:string};message?:string}};message?:string};return value.response?.data?.error?.message||value.response?.data?.message||value.message||'Syllabus action failed.';};
function subjectGuessId(text:string|undefined,subjects:Array<{id:string;name:string}>|undefined){if(!text||!subjects)return '';const normalize=(value:string)=>value.toLowerCase().replace(/maths?/g,'mathematics').replace(/social studies/g,'social science').replace(/[^a-z0-9]+/g,' ').trim();const target=normalize(text);return [...subjects].sort((a,b)=>b.name.length-a.name.length).find(item=>{const name=normalize(item.name);return target===name||(` ${target} `).includes(` ${name} `);})?.id||'';}
function gradeFromOfficialPdfName(name:string){const match=name.match(/secp(?:art)?\d*(xii|xi|ix|x|viii|vii|vi|iv|v|iii|ii|i|1[0-2]|[1-9])(?=$|[_\-.])/i);if(!match)return null;const value=match[1].toUpperCase();const roman:Record<string,number>={I:1,II:2,III:3,IV:4,V:5,VI:6,VII:7,VIII:8,IX:9,X:10,XI:11,XII:12};const grade=roman[value]||Number(value);return grade>=1&&grade<=12?`CLASS_${grade}`:null;}
function parseCsv(input:string){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<input.length;i++){const ch=input[i];if(quoted){if(ch==='"'&&input[i+1]==='"'){cell+='"';i++;}else if(ch==='"')quoted=false;else cell+=ch;}else if(ch==='"')quoted=true;else if(ch===','){row.push(cell);cell='';}else if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell='';}else if(ch!=='\r')cell+=ch;}if(quoted)throw Error('CSV has an unclosed quoted field.');if(cell.length||row.length){row.push(cell);rows.push(row);}return rows.filter(item=>item.some(value=>value.trim()));}
function rowsFromMatrix(matrix:unknown[][]):FrameworkImportRow[]{if(matrix.length<2)throw Error('Add a header and at least one topic row.');const found=matrix[0].map(value=>String(value??'').replace(/^\uFEFF/,'').trim().toLowerCase());const missing=headers.filter(header=>!found.includes(header));if(missing.length)throw Error(`Missing columns: ${missing.join(', ')}`);return matrix.slice(1).filter(values=>values.some(value=>String(value??'').trim())).map((values,index)=>{const get=(key:string)=>String(values[found.indexOf(key)]??'').trim();return {boardCode:get('board_code'),medium:get('medium') as 'en'|'hi',academicYear:get('academic_year'),gradeCode:get('class_code'),subjectCode:get('subject_code'),unit:get('unit'),chapter:get('chapter'),topic:get('topic'),topicHi:get('topic_hi')||undefined,learningOutcome:get('learning_outcome'),sourceUrl:get('source_url'),pageReference:get('page_reference'),sortOrder:get('sort_order')||String(index+1)};});}
async function readSpreadsheet(file:File){if(file.name.toLowerCase().endsWith('.csv'))return rowsFromMatrix(parseCsv(await file.text()));const {default:ExcelJS}=await import('exceljs');const workbook=new ExcelJS.Workbook();await workbook.xlsx.load(await file.arrayBuffer());const sheet=workbook.worksheets[0];if(!sheet)throw Error('The workbook has no worksheet.');const matrix:string[][]=[];sheet.eachRow({includeEmpty:true},row=>matrix.push(Array.from({length:row.cellCount},(_value,index)=>row.getCell(index+1).text)));return rowsFromMatrix(matrix);}
async function downloadTemplate(){const {default:ExcelJS}=await import('exceljs');const sample=[headers,['CBSE','en','2026-27','CLASS_9','MATHEMATICS','Unit I · Number System','Number System','Rational numbers','','Explain rational numbers','https://cbseacademic.nic.in/...','Page 4','1']];const book=new ExcelJS.Workbook();const sheet=book.addWorksheet('Syllabus');sheet.addRows(sample);sheet.getRow(1).font={bold:true};sheet.columns=sheet.columns.map(column=>({...column,width:22}));const buffer=await book.xlsx.writeBuffer();const url=URL.createObjectURL(new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const link=document.createElement('a');link.href=url;link.download='vidyasetu-syllabus-template.xlsx';link.click();URL.revokeObjectURL(url);}
const panel='rounded-2xl border border-slate-200 bg-white p-5 shadow-sm';
const label='block text-sm font-semibold text-slate-700';

export default function AdminSyllabus(){
 const client=useQueryClient();const now=new Date();const sessionStart=now.getMonth()<3?now.getFullYear()-1:now.getFullYear();const defaultYear=`${sessionStart}-${String(sessionStart+1).slice(-2)}`;
 const [tab,setTab]=useState<Tab>('library');
 const [filterBoard,setFilterBoard]=useState('');const [filterGrade,setFilterGrade]=useState('');const [filterSubject,setFilterSubject]=useState('');const [filterYear,setFilterYear]=useState('');const [search,setSearch]=useState('');
 const [documentId,setDocumentId]=useState('');const [versionId,setVersionId]=useState('');
 const [viewVersionId,setViewVersionId]=useState('');const [scopeNote,setScopeNote]=useState('');const [showRemoved,setShowRemoved]=useState(false);
 const [board,setBoard]=useState('CBSE');const [year,setYear]=useState(defaultYear);const [medium,setMedium]=useState<'en'|'hi'>('en');const [grade,setGrade]=useState('');const [subject,setSubject]=useState('');const [officialIndex,setOfficialIndex]=useState('');const [uploadSource,setUploadSource]=useState('');const [title,setTitle]=useState('');
 const [files,setFiles]=useState<File[]>([]);const [discovered,setDiscovered]=useState<OfficialSyllabusDocument[]>([]);const [selectedUrls,setSelectedUrls]=useState<string[]>([]);const [scopeByUrl,setScopeByUrl]=useState<Record<string,{gradeCode:string;subjectId:string}>>({});const [rejectedCount,setRejectedCount]=useState(0);const [fetchNotice,setFetchNotice]=useState('');
 const [sheetRows,setSheetRows]=useState<FrameworkImportRow[]>([]);const [sheetName,setSheetName]=useState('');
 const [editTitle,setEditTitle]=useState('');const [editGrade,setEditGrade]=useState('');const [editSubject,setEditSubject]=useState('');const [editSource,setEditSource]=useState('');const [editLanguage,setEditLanguage]=useState<'en'|'hi'>('en');
 const [reviewNote,setReviewNote]=useState('');const [rightsConfirmed,setRightsConfirmed]=useState(false);const [rightsEvidence,setRightsEvidence]=useState('');const [statusNote,setStatusNote]=useState('');const [confirmed,setConfirmed]=useState(false);const [editingTopic,setEditingTopic]=useState<SyllabusTopic|null>(null);
 const [newTopic,setNewTopic]=useState({gradeCode:'',subjectId:'',unit:'',chapter:'',topic:'',topicHi:'',learningOutcome:'',pageReference:'',sortOrder:'0'});
 const options=useQuery({queryKey:['syllabus-options'],queryFn:()=>getSyllabusOptions().then(response=>response.data.data)});
 const sources=useQuery({queryKey:['syllabus-sources'],queryFn:()=>getSyllabusSources().then(response=>response.data.data)});
 const documents=useQuery({queryKey:['syllabus-documents',filterBoard,filterGrade,filterSubject,filterYear,search],queryFn:()=>getSyllabusDocuments({boardCode:filterBoard,gradeCode:filterGrade,subjectId:filterSubject,academicYear:filterYear,query:search},true).then(response=>response.data.data)});
 const document=useQuery({queryKey:['syllabus-document',documentId],queryFn:()=>getSyllabusDocument(documentId,true).then(response=>response.data.data),enabled:Boolean(documentId)});
 const version=useQuery({queryKey:['syllabus-detail',versionId],queryFn:()=>getSyllabusDetail(versionId).then(response=>response.data.data),enabled:Boolean(versionId)});
 const viewVersion=useQuery({queryKey:['syllabus-detail',viewVersionId],queryFn:()=>getSyllabusDetail(viewVersionId).then(response=>response.data.data),enabled:Boolean(viewVersionId)});
 const coverage=useQuery({queryKey:['framework-coverage'],queryFn:()=>getFrameworkCoverage().then(response=>response.data.data)});
 const refresh=async()=>{await Promise.all([client.invalidateQueries({queryKey:['syllabus-documents']}),client.invalidateQueries({queryKey:['syllabus-document']}),client.invalidateQueries({queryKey:['syllabus-options']}),client.invalidateQueries({queryKey:['syllabus-detail']}),client.invalidateQueries({queryKey:['framework-coverage']})]);};
 useEffect(()=>{const doc=document.data;if(!doc)return;setEditTitle(doc.title);setEditGrade(doc.grade_code||'');setEditSubject(doc.subject_id||'');setEditSource(doc.source_url||'');setEditLanguage(doc.language?.startsWith('hi')?'hi':'en');},[document.data]);
 useEffect(()=>{if(!board)return;setOfficialIndex(sources.data?.find(item=>item.boardCode===board)?.url||'');setDiscovered([]);setSelectedUrls([]);setScopeByUrl({});},[board,sources.data]);
 useEffect(()=>{setDiscovered([]);setSelectedUrls([]);setScopeByUrl({});setRejectedCount(0);setFetchNotice('');},[grade,subject,year,medium,officialIndex]);
 const subjectName=options.data?.subjects.find(item=>item.id===subject)?.name;
 const discover=useMutation({
  mutationFn:()=>discoverOfficialSyllabusDocuments({boardCode:board,sourceUrl:officialIndex,academicYear:year,classCode:grade,subject:subjectName||undefined}).then(response=>response.data.data),
  onSuccess:data=>{
   const exactMatches=data.documents.filter(item=>item.classGuess===grade&&(!subjectName||item.subjectGuess===subjectName));
   setRejectedCount(data.documents.length-exactMatches.length);
   setDiscovered(exactMatches);
   setSelectedUrls(exactMatches.slice(0,15).map(item=>item.url));
   setScopeByUrl(Object.fromEntries(exactMatches.map(item=>[item.url,{gradeCode:grade,subjectId:subject||subjectGuessId(item.subjectGuess||item.title,options.data?.subjects)||''}])));
   const scope=[options.data?.grades.find(item=>item.code===grade)?.name||grade,subjectName||'all subjects',board,year].join(' · ');
   const notice=data.message||(!exactMatches.length?`No verified syllabus PDFs matched ${scope}. No unrelated class results were kept.`:`Found ${exactMatches.length} verified PDF${exactMatches.length===1?'':'s'} for ${scope}. Load the selected PDFs as Drafts to review and edit.`);
   setFetchNotice(notice);
   if(data.outcome==='UNSUPPORTED_SCOPE'||(!exactMatches.length&&!data.message))toast.error(notice);else toast(notice);
  },
  onMutate:()=>{setDiscovered([]);setSelectedUrls([]);setScopeByUrl({});setRejectedCount(0);setFetchNotice('Fetching the selected class and subject from the official source…');},
  onError:error=>{setDiscovered([]);setSelectedUrls([]);setScopeByUrl({});setRejectedCount(0);setFetchNotice(`Syllabus source could not be fetched: ${message(error)}`);toast.error(`Syllabus source could not be fetched: ${message(error)}`);},
 });
 const importOfficial=useMutation({mutationFn:async()=>{const selected=discovered.filter(item=>selectedUrls.includes(item.url));if(!selected.length)throw Error('Select at least one PDF.');if(selected.length>15)throw Error('Import up to 15 PDFs per batch.');const missing=selected.find(item=>!(grade||scopeByUrl[item.url]?.gradeCode||item.classGuess)||!(subject||scopeByUrl[item.url]?.subjectId||subjectGuessId(item.subjectGuess||item.title,options.data?.subjects)));if(missing)throw Error(`Choose a class and subject for “${missing.title}” before importing.`);type Result={ok:boolean;item:OfficialSyllabusDocument;data?:{documentId?:string;versionId?:string|null;requiresScope?:boolean};error?:string};const results:Result[]=[];for(let i=0;i<selected.length;i+=2){await Promise.all(selected.slice(i,i+2).map(async item=>{const itemGrade=grade||scopeByUrl[item.url]?.gradeCode||item.classGuess||'';const itemSubject=subject||scopeByUrl[item.url]?.subjectId||subjectGuessId(item.subjectGuess||item.title,options.data?.subjects)||'';try{const response=await importSyllabusDocument({boardCode:board,academicYear:year,gradeCode:itemGrade,subjectId:itemSubject,title:item.title,language:medium,sourceUrl:item.url,pdfUrl:item.url,sourcePublisher:'Official board source'});const data=response.data.data as Result['data'];if(!data?.documentId)throw Error('The server did not confirm that the PDF was stored.');if(!data.versionId||data.requiresScope){results.push({ok:false,item,data,error:'PDF stored, but a syllabus Draft was not created. Assign the class and subject from its document details.'});return;}results.push({ok:true,item,data});}catch(error){results.push({ok:false,item,error:message(error)});}}));}return results;},onSuccess:async results=>{const ok=results.filter(item=>item.ok);const failed=results.filter(item=>!item.ok);const savedWithoutDraft=failed.filter(item=>Boolean(item.data?.documentId));const handledUrls=new Set([...ok,...savedWithoutDraft].map(item=>item.item.url));const retryUrls=new Set(failed.filter(item=>!item.data?.documentId).map(item=>item.item.url));const remaining=discovered.filter(item=>!handledUrls.has(item.url));setDiscovered(remaining);setSelectedUrls(current=>{const retry=current.filter(url=>retryUrls.has(url));return retry.length?retry:remaining.slice(0,15).map(item=>item.url);});if(ok.length){const scopes=[...new Set(ok.map(item=>{const gradeCode=grade||scopeByUrl[item.item.url]?.gradeCode||item.item.classGuess||'';const subjectId=subject||scopeByUrl[item.item.url]?.subjectId||subjectGuessId(item.item.subjectGuess||item.item.title,options.data?.subjects)||'';return `${options.data?.grades.find(value=>value.code===gradeCode)?.name||gradeCode} · ${options.data?.subjects.find(value=>value.id===subjectId)?.name||'subject'} · ${board}`;}))];toast.success(`Syllabus imported as Draft: ${scopes.join('; ')}. Verify the extracted index and topics before review.`);}failed.forEach(item=>toast.error(`${item.item.title}: ${item.error}`));if(!failed.length&&remaining.length)toast('The next batch is selected. Import again to continue.');await refresh();const documentToOpen=ok[0]?.data?.documentId||savedWithoutDraft[0]?.data?.documentId;if(documentToOpen){setDocumentId(documentToOpen);setTab('library');}},onError:error=>toast.error(message(error))});
 const upload=useMutation({mutationFn:async()=>{if(!files.length)throw Error('Choose at least one PDF.');if(!board)throw Error('Choose a board.');const mismatch=files.map(file=>({file,grade:gradeFromOfficialPdfName(file.name)})).find(item=>grade&&item.grade&&grade!==item.grade);if(mismatch)throw Error(`${mismatch.file.name} appears to be ${mismatch.grade!.replace('CLASS_','Class ')}, but ${grade.replace('CLASS_','Class ')} is selected. Choose the matching class or upload the correct PDF.`);const form=new FormData();files.forEach(file=>form.append('files',file));form.append('boardCode',board);form.append('academicYear',year);form.append('gradeCode',grade);form.append('subjectId',subject);form.append('title',files.length===1?title:'');form.append('language',medium);form.append('sourceUrl',uploadSource);form.append('sourcePublisher','Official board source');return uploadSyllabusDocuments(form).then(response=>response.data.data);},onSuccess:async data=>{data.results.forEach(result=>result.ok?toast.success(`${result.file}: uploaded and extracted`):toast.error(`${result.file}: ${result.error}`));setFiles([]);await refresh();const first=data.results.find(item=>item.ok)?.data;if(first?.documentId){setDocumentId(first.documentId);setTab('library');}},onError:error=>toast.error(message(error))});
 const preview=useMutation({mutationFn:()=>previewFrameworkImport(sheetRows).then(response=>response.data.data),onError:error=>toast.error(message(error))});
 const saveSheet=useMutation({mutationFn:()=>commitFrameworkImport(sheetRows),onSuccess:async()=>{toast.success('Spreadsheet imported and saved as Draft.');setSheetRows([]);setSheetName('');preview.reset();await refresh();setTab('review');},onError:error=>toast.error(message(error))});
 const updateDoc=useMutation({mutationFn:()=>updateSyllabusDocument(documentId,{gradeCode:editGrade||null,subjectId:editSubject||null,title:editTitle,sourceUrl:editSource||null,language:editLanguage}),onSuccess:async()=>{toast.success('Syllabus details updated and Draft rebuilt.');await refresh();},onError:error=>toast.error(message(error))});
 const removeDoc=useMutation({mutationFn:()=>deleteSyllabusDocument(documentId),onSuccess:async()=>{toast.success('Incorrect Draft and stored PDF removed.');setDocumentId('');await refresh();},onError:error=>toast.error(message(error))});
 const reviewDoc=useMutation({mutationFn:(status:'APPROVED'|'REJECTED')=>reviewSyllabusDocument(documentId,{status,note:reviewNote,redistributionAllowed:status==='APPROVED'&&rightsConfirmed&&Boolean(rightsEvidence),redistributionEvidenceUrl:rightsEvidence||undefined}),onSuccess:async()=>{toast.success('Document review recorded.');await refresh();},onError:error=>toast.error(message(error))});
 const status=useMutation({mutationFn:(value:string)=>changeSyllabusStatus(versionId,value,statusNote),onSuccess:async(_data,value)=>{toast.success(value==='REVIEWED'?'Syllabus submitted for academic review.':value==='ACTIVE'?'Syllabus published. It is now available in My Syllabus for students whose board, class, year and medium match.':value==='ARCHIVED'?'Syllabus archived.':'Syllabus returned to Draft.');setConfirmed(false);await refresh();},onError:error=>toast.error(message(error))});
 const updateTopic=useMutation({mutationFn:(topic:SyllabusTopic)=>updateSyllabusTopic(topic.id,{unit:topic.unit||topic.chapter,chapter:topic.chapter,topic:topic.title,topicHi:topic.title_hi||null,learningOutcome:topic.learning_outcome||null,pageReference:topic.page_reference,sortOrder:topic.sort_order}),onSuccess:async()=>{toast.success('Topic updated.');setEditingTopic(null);await refresh();},onError:error=>toast.error(message(error))});
 const createTopic=useMutation({mutationFn:()=>addSyllabusTopic(versionId,{...newTopic,topicHi:newTopic.topicHi||null,learningOutcome:newTopic.learningOutcome||null,sortOrder:Number(newTopic.sortOrder)||0}),onSuccess:async()=>{toast.success('Missing topic added to the Draft.');setNewTopic(current=>({...current,unit:'',chapter:'',topic:'',topicHi:'',learningOutcome:'',pageReference:'',sortOrder:'0'}));await refresh();},onError:error=>toast.error(message(error))});
 const retire=useMutation({mutationFn:(topic:SyllabusTopic)=>retireSyllabusTopic(topic.id,!topic.is_retired,statusNote),onSuccess:async()=>{toast.success('Topic visibility updated.');await refresh();},onError:error=>toast.error(message(error))});
 const changeScope=useMutation({mutationFn:(input:{gradeCode:string;subjectId:string;retired:boolean})=>changeSyllabusScope(viewVersionId,{...input,note:scopeNote}),onSuccess:async()=>{toast.success('Class and subject scope updated in this Draft.');setScopeNote('');await refresh();},onError:error=>toast.error(message(error))});
 const groupedTopics=useMemo(()=>{const map=new Map<string,SyllabusTopic[]>();for(const topic of version.data?.topics||[]){if(filterGrade&&topic.grade_code!==filterGrade)continue;if(filterSubject&&topic.subject_id!==filterSubject)continue;const key=`${topic.grade_code} · ${topic.subject} · ${topic.unit||topic.chapter} · ${topic.chapter}`;map.set(key,[...(map.get(key)||[]),topic]);}return [...map];},[version.data,filterGrade,filterSubject]);
 const visibleVersions=(options.data?.versions||[]).filter(item=>(!filterBoard||item.board_code===filterBoard)&&(!filterYear||item.academic_year===filterYear));
 const selectedViewTopics=(viewVersion.data?.topics||[]).filter(topic=>(!filterGrade||topic.grade_code===filterGrade)&&(!filterSubject||topic.subject_id===filterSubject)&&(showRemoved||!topic.is_retired));
 const viewGroups=useMemo(()=>{const map=new Map<string,SyllabusTopic[]>();for(const topic of selectedViewTopics){const key=`${topic.grade_code} · ${topic.subject} · ${topic.unit||topic.chapter} · ${topic.chapter}`;map.set(key,[...(map.get(key)||[]),topic]);}return [...map];},[selectedViewTopics]);
 const selectedScope=filterGrade&&filterSubject?viewVersion.data?.topics.filter(topic=>topic.grade_code===filterGrade&&topic.subject_id===filterSubject)||[]:[];
 const scopeRemoved=selectedScope.length>0&&selectedScope.every(topic=>topic.is_retired);
 const covered=coverage.data?.filter(item=>item.topic_count>0).length||0;
 const missingSelectedScope=discovered.some(item=>selectedUrls.includes(item.url)&&(!(grade||scopeByUrl[item.url]?.gradeCode||item.classGuess)||!(subject||scopeByUrl[item.url]?.subjectId||subjectGuessId(item.subjectGuess||item.title,options.data?.subjects))));
 return <main className="mx-auto max-w-7xl p-4 text-slate-900 md:p-7">
  <header className={panel}><div className="flex flex-wrap items-end justify-between gap-3"><div><h1 className="text-3xl font-bold text-slate-950">Syllabus Manager</h1><p className="mt-1 text-slate-600">View the syllabus index and topic structure, manage Drafts, and review publication. Lesson content is created separately in Content Creator.</p></div><div className="rounded-xl bg-orange-50 px-4 py-2 text-sm font-semibold text-orange-900">{options.data?.versions.length||0} syllabus versions · {covered} covered scopes</div></div></header>
  <nav className="my-5 flex flex-wrap gap-2" aria-label="Syllabus Manager sections">{([['library','View syllabus'],['import','Fetch / add syllabus'],['review','Review & publish']] as [Tab,string][]).map(([value,text])=><button key={value} className={tab===value?'btn-primary':'btn-secondary'} onClick={()=>setTab(value)}>{text}</button>)}</nav>

  {tab==='library'&&<div className="space-y-5">
   <section className={panel}><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">View syllabus</h2><p className="text-sm text-slate-600">View imported syllabus indexes, units, chapters and topics by board, class and subject. Leave Subject on “All subjects” to see every loaded subject for that class. Draft and reviewed records are admin-only; students see published records in My Syllabus.</p></div><button className="btn-primary" onClick={()=>setTab('import')}>+ Add syllabus</button></div>
    <div className="mt-4 grid gap-3 md:grid-cols-4"><label className={label}>Board<select className="admin-select" value={filterBoard} onChange={event=>{setFilterBoard(event.target.value);setViewVersionId('');}}><option value="">All boards</option>{options.data?.boards.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Class<select className="admin-select" value={filterGrade} onChange={event=>setFilterGrade(event.target.value)}><option value="">All classes</option>{options.data?.grades.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Subject<select className="admin-select" value={filterSubject} onChange={event=>setFilterSubject(event.target.value)}><option value="">All subjects</option>{options.data?.subjects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={label}>Academic year<select className="admin-select" value={filterYear} onChange={event=>{setFilterYear(event.target.value);setViewVersionId('');}}><option value="">All academic years</option>{[...new Set((options.data?.versions||[]).map(item=>item.academic_year))].sort().reverse().map(item=><option key={item} value={item}>{item}</option>)}</select></label></div>
    <label className={`${label} mt-4`}>Syllabus<select className="admin-select" value={viewVersionId} onChange={event=>setViewVersionId(event.target.value)}><option value="">Select board/year syllabus</option>{visibleVersions.map(item=><option key={item.id} value={item.id}>{item.board_code} · {item.academic_year} · {item.medium||'en'} · {item.title} · {item.publication_status||item.status}</option>)}</select></label>
    {viewVersion.isLoading&&<p className="mt-4">Loading syllabus topics…</p>}{viewVersion.isError&&<p className="mt-4 text-red-700" role="alert">Could not load this syllabus version.</p>}
    {viewVersion.data&&<div className="mt-4 rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-lg font-bold">{viewVersion.data.version.title}</h3><p className="text-sm text-slate-600">{viewVersion.data.version.board_code} · {viewVersion.data.version.academic_year} · {viewVersion.data.version.medium||'en'} · {viewVersion.data.version.publication_status||viewVersion.data.version.status} · {selectedViewTopics.length} topics shown</p></div><button className="btn-secondary" onClick={()=>{setVersionId(viewVersionId);setTab('review');}}>Edit / review topics →</button></div>
     {viewVersion.data.version.publication_status==='DRAFT'&&filterGrade&&filterSubject&&selectedScope.length>0&&<div className="mt-4 rounded-lg border border-amber-300 bg-amber-50 p-3"><p className="font-semibold">Class and subject scope: {options.data?.grades.find(item=>item.code===filterGrade)?.name||filterGrade} · {options.data?.subjects.find(item=>item.id===filterSubject)?.name}</p><p className="mt-1 text-sm text-slate-700">Remove this scope from this Draft or restore it. Removal is audited and can be reversed; published syllabus versions remain unchanged.</p><label className={`${label} mt-2`}>Reason (at least 10 characters)<input className="admin-input" value={scopeNote} onChange={event=>setScopeNote(event.target.value)} placeholder="Explain the correction"/></label><button className="btn-secondary mt-2" disabled={changeScope.isPending||scopeNote.trim().length<10} onClick={()=>{const retired=!scopeRemoved;if(window.confirm(`${retired?'Remove':'Restore'} all ${selectedScope.length} topics for this class and subject in the Draft?`))changeScope.mutate({gradeCode:filterGrade,subjectId:filterSubject,retired});}}>{changeScope.isPending?'Saving…':scopeRemoved?'Restore this class + subject':'Remove this class + subject from Draft'}</button></div>}
     <label className="mt-4 flex items-center gap-2 text-sm"><input type="checkbox" checked={showRemoved} onChange={event=>setShowRemoved(event.target.checked)}/>Show removed topics</label>
     <div className="mt-3 space-y-3">{viewGroups.map(([key,topics])=><details key={key} className="rounded-lg border border-slate-200 bg-white p-3"><summary className="cursor-pointer font-semibold">{key} <span className="font-normal text-slate-500">({topics.length} topics)</span></summary><ul className="mt-3 space-y-2">{topics.map(topic=><li key={topic.id} className={`rounded-lg border p-3 ${topic.is_retired?'bg-slate-100 text-slate-500':''}`}><div className="font-medium">{topic.title}{topic.title_hi&&<span className="ml-2 text-slate-600">{topic.title_hi}</span>}{topic.is_retired&&<span className="ml-2 text-xs font-semibold">Removed</span>}</div><div className="mt-1 text-sm text-slate-600">Page: {topic.page_reference||'—'}{topic.learning_outcome&&` · Outcome: ${topic.learning_outcome}`}</div></li>)}</ul></details>)}{!viewGroups.length&&<p className="rounded-lg bg-white p-4 text-slate-600">No topics match these filters in this syllabus.</p>}</div>
    </div>}
   </section>
   <section className={panel}><h2 className="text-xl font-bold">Source PDF documents</h2><p className="text-sm text-slate-600">Reference files and extraction records are managed separately from the structured syllabus shown above.</p><div className="mt-4 grid gap-3 md:grid-cols-3"><label className={label}>Search documents<input className="admin-input" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Document title"/></label></div>{documents.isLoading&&<p className="mt-3">Loading source documents…</p>}{documents.isError&&<p className="mt-3 text-red-700" role="alert">Could not load source documents.</p>}<div className="mt-3 space-y-3">{documents.data?.map(item=><article key={item.id} className="rounded-xl border border-slate-200 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">{item.title}</h3><p className="text-sm text-slate-600">{item.board_name||item.board_code} · {item.grade_name||item.detected_grade_code||'Class needs confirmation'} · {item.subject_name||item.detected_subject||'Subject needs confirmation'} · {item.academic_year}</p><p className="mt-1 text-xs">Document: {item.status} · {item.topic_count||0} extracted topics</p></div><button className="btn-secondary" onClick={()=>setDocumentId(item.id)}>View PDF / manage</button></div></article>)}{!documents.isLoading&&!documents.data?.length&&<p className="rounded-xl bg-slate-50 p-4 text-slate-600">No source PDF documents match these filters. Structured syllabus versions are shown above.</p>}</div></section>
   {documentId&&document.data&&<DocumentPanel doc={document.data} options={options.data} edit={{title:editTitle,grade:editGrade,subject:editSubject,source:editSource,language:editLanguage}} setters={{title:setEditTitle,grade:setEditGrade,subject:setEditSubject,source:setEditSource,language:setEditLanguage}} onClose={()=>setDocumentId('')} onSave={()=>updateDoc.mutate()} saving={updateDoc.isPending} onDelete={()=>{if(window.confirm('Delete this incorrect Draft, its extracted structure and stored PDF?'))removeDoc.mutate();}} deleting={removeDoc.isPending} review={{note:reviewNote,rights: rightsConfirmed,evidence:rightsEvidence}} reviewSetters={{note:setReviewNote,rights:setRightsConfirmed,evidence:setRightsEvidence}} onReview={value=>reviewDoc.mutate(value)} reviewing={reviewDoc.isPending} onOpenVersion={()=>{if(document.data?.version_id){setVersionId(document.data.version_id);setTab('review');}}}/>}
  </div>}

  {tab==='import'&&<div className="space-y-5">
   <section className={panel}><h2 className="text-xl font-bold">Import scope</h2><p className="text-sm text-slate-600">Board, year and medium are required. Class and subject may be detected from a PDF; VidyaSetu blocks a conflicting selection.</p><div className="mt-4 grid gap-3 md:grid-cols-5"><label className={label}>Board<select className="admin-select" value={board} onChange={event=>setBoard(event.target.value)}><option value="">Select board</option>{options.data?.boards.filter(item=>item.code!=='COMMON').map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Academic year<input className="admin-input" value={year} onChange={event=>setYear(event.target.value)}/></label><label className={label}>Medium<select className="admin-select" value={medium} onChange={event=>setMedium(event.target.value as 'en'|'hi')}><option value="en">English</option><option value="hi">Hindi</option></select></label><label className={label}>Class (required for fetch)<select className="admin-select" value={grade} onChange={event=>setGrade(event.target.value)}><option value="">Select class</option>{options.data?.grades.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Subject (optional)<select className="admin-select" value={subject} onChange={event=>setSubject(event.target.value)}><option value="">Detect from PDF</option>{options.data?.subjects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div></section>
   <section className={panel}><h2 className="text-xl font-bold">1. Fetch syllabus index from an official source</h2><p className="text-sm text-slate-600">Choose the board, academic year, class and optionally one subject (leave Subject blank for all subjects in that class). Fetch only matching official PDFs, load selected PDFs as Drafts, then view, edit or delete their syllabus index and topics before submitting and publishing.</p><div className="mt-3 flex flex-wrap items-end gap-3"><label className={`${label} min-w-[280px] flex-1`}>Official source<select className="admin-select" value={officialIndex} onChange={event=>setOfficialIndex(event.target.value)}><option value="">Select source</option>{sources.data?.filter(item=>item.boardCode===board).map(item=><option key={item.url} value={item.url}>{item.name}</option>)}</select></label><button className="btn-primary" disabled={discover.isPending||!board||!officialIndex||!grade} onClick={()=>{if(!board||!officialIndex||!grade)return toast.error('Choose a board, official source and class.');discover.mutate();}}>{discover.isPending?'Fetching PDFs…':'Fetch syllabus PDFs'}</button></div>{fetchNotice&&<p className="mt-3 rounded-lg border border-blue-200 bg-blue-50 p-3 text-sm text-slate-800" role="status">{fetchNotice}</p>}{rejectedCount>0&&<p className="mt-3 rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm text-amber-950" role="status">{rejectedCount} result(s) were excluded because their class or subject did not exactly match this search.</p>}{sources.data?.find(item=>item.url===officialIndex)?.note&&<p className="mt-2 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-slate-700" role="note">Source scope: {sources.data.find(item=>item.url===officialIndex)?.note}</p>}{sources.isSuccess&&board&&!sources.data?.some(item=>item.boardCode===board)&&<p className="mt-2 rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm text-slate-800" role="status">Automatic fetching is not configured for this board yet. Load its verified official PDF or reviewed syllabus spreadsheet in the sections below; the system will still create a Draft for admin review.</p>}
    {discovered.length>0&&<div className="mt-4 space-y-3"><p className="text-sm text-slate-700">The first 15 matches are selected. Confirm each class and subject. Import downloads and retains the source PDF for verification, extracts only the syllabus index/topics, discards extracted lesson text, and saves the structure as Drafts. Verify the extracted structure before submitting for review; students see it only after publication.</p><div className="max-h-[32rem] space-y-3 overflow-auto rounded-xl border border-slate-200 p-3">{discovered.map(item=><article key={item.url} className="rounded-xl border border-slate-200 bg-white p-3"><label className="flex items-start gap-3"><input type="checkbox" checked={selectedUrls.includes(item.url)} disabled={!selectedUrls.includes(item.url)&&selectedUrls.length>=15} onChange={event=>setSelectedUrls(current=>event.target.checked?[...current,item.url]:current.filter(value=>value!==item.url))}/><span><strong>{item.title}</strong><small className="block text-slate-600">Detected: {item.classGuess?.replace('CLASS_','Class ')||'choose class'} · {item.subjectGuess||'choose subject'} · {item.sourceHost}</small><a className="break-all text-xs underline" href={item.url} target="_blank" rel="noopener noreferrer" onClick={event=>event.stopPropagation()}>Preview official PDF (does not import) ↗</a></span></label><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className={label}>Class<select className="admin-select" value={grade||scopeByUrl[item.url]?.gradeCode||item.classGuess||''} onChange={event=>setScopeByUrl(current=>({...current,[item.url]:{gradeCode:event.target.value,subjectId:current[item.url]?.subjectId||''}}))}><option value="">Choose class</option>{options.data?.grades.map(option=><option key={option.code} value={option.code}>{option.name}</option>)}</select></label><label className={label}>Subject<select className="admin-select" value={subject||scopeByUrl[item.url]?.subjectId||subjectGuessId(item.subjectGuess||item.title,options.data?.subjects)} onChange={event=>setScopeByUrl(current=>({...current,[item.url]:{gradeCode:current[item.url]?.gradeCode||'',subjectId:event.target.value}}))}><option value="">Choose subject</option>{options.data?.subjects.map(option=><option key={option.id} value={option.id}>{option.name}</option>)}</select></label></div></article>)}</div><button className="btn-primary" disabled={!selectedUrls.length||missingSelectedScope||importOfficial.isPending} onClick={()=>importOfficial.mutate()}>{importOfficial.isPending?'Downloading, extracting and saving…':`Import ${selectedUrls.length} selected PDF${selectedUrls.length===1?'':'s'} as syllabus Draft${selectedUrls.length===1?'':'s'}`}</button><p className="text-sm text-slate-600">{missingSelectedScope?'Choose a class and subject for each selected PDF.':'Up to 15 per batch; the next batch is selected after saving.'}</p></div>}
   </section>
   <section className={panel}><h2 className="text-xl font-bold">Alternative: load an official syllabus PDF</h2><p className="text-sm text-slate-600">Upload up to 10 text-based PDFs. Title, class and subject are detected where possible. Official source URL is required before approval, not before upload.</p><div className="mt-3 grid gap-3 md:grid-cols-2"><label className={label}>PDF files<input className="mt-2 block w-full" type="file" accept="application/pdf,.pdf" multiple onChange={event=>{upload.reset();setFiles(Array.from(event.target.files||[]).slice(0,10));}}/></label><label className={label}>Title override (one file only)<input className="admin-input" value={title} onChange={event=>setTitle(event.target.value)} placeholder="Uses filename when blank"/></label><label className={`${label} md:col-span-2`}>Official source URL (optional for Draft)<input className="admin-input" type="url" value={uploadSource} onChange={event=>setUploadSource(event.target.value)} placeholder="Add now, or before document approval"/></label></div>{files.length>0&&<p className="mt-2 text-sm">Selected: {files.map(file=>file.name).join(', ')}</p>}{upload.error&&<p className="mt-2 rounded-lg border border-red-300 bg-red-50 p-3 text-sm text-red-900" role="alert">{message(upload.error)}</p>}<button className="btn-primary mt-3" disabled={upload.isPending} onClick={()=>upload.mutate()}>{upload.isPending?'Uploading, scanning and extracting…':`Upload and create Draft${files.length>1?'s':''}`}</button>
   </section>
   <section className={panel}><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">Alternative: load syllabus index/topics by spreadsheet</h2><p className="text-sm text-slate-600">Use one workbook for a board, year and medium; it may contain all classes and subjects.</p></div><button className="btn-secondary" onClick={()=>void downloadTemplate().catch(error=>toast.error(message(error)))}>Download Excel template</button></div><input className="mt-4" type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={async event=>{const file=event.target.files?.[0];if(!file)return;try{setSheetRows(await readSpreadsheet(file));setSheetName(file.name);preview.reset();}catch(error){toast.error(message(error));setSheetRows([]);}}}/>{sheetName&&<p className="mt-2">{sheetName} · {sheetRows.length} topic rows</p>}{sheetRows.length>0&&<button className="btn-primary mt-3" disabled={preview.isPending} onClick={()=>preview.mutate()}>{preview.isPending?'Validating…':'Preview and validate'}</button>}{preview.data&&<div className={`mt-4 rounded-xl border p-4 ${preview.data.valid?'border-green-300 bg-green-50':'border-red-300 bg-red-50'}`}><strong>{preview.data.valid?'Ready to import':'Correct validation errors'}</strong><p>{preview.data.rowCount} topics · {preview.data.classes.length} classes · {preview.data.subjectScopes} class/subject scopes</p>{preview.data.errors.length>0&&<ul className="mt-2 list-disc pl-6">{preview.data.errors.slice(0,100).map((error,index)=><li key={index}>{error.row?`Row ${error.row}: `:''}{error.message}</li>)}</ul>}<button className="btn-primary mt-3" disabled={!preview.data.valid||saveSheet.isPending} onClick={()=>saveSheet.mutate()}>{saveSheet.isPending?'Saving Draft…':'Save spreadsheet as Draft'}</button></div>}</section>
  </div>}

  {tab==='review'&&<section className={panel}><h2 className="text-xl font-bold">Review and publish</h2><p className="text-sm text-slate-600">Verify the structured tree against its official source. Only Published syllabi reach matching students. Choose a class and subject to edit a specific scope.</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className={label}>Class<select className="admin-select" value={filterGrade} onChange={event=>setFilterGrade(event.target.value)}><option value="">All classes</option>{options.data?.grades.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Subject<select className="admin-select" value={filterSubject} onChange={event=>setFilterSubject(event.target.value)}><option value="">All subjects</option>{options.data?.subjects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><label className={`${label} mt-4`}>Syllabus version<select className="admin-select" value={versionId} onChange={event=>{setVersionId(event.target.value);setConfirmed(false);}}><option value="">Select a version</option>{options.data?.versions.map(item=><option key={item.id} value={item.id}>{item.board_code} · {item.academic_year} · {item.medium||'en'} · {item.title} · {item.publication_status||item.status}</option>)}</select></label>
   {version.isLoading&&<p className="mt-4">Loading syllabus…</p>}{version.isError&&<p className="mt-4 text-red-700">Could not load this syllabus.</p>}{version.data&&<div className="mt-5"><div className="flex flex-wrap justify-between gap-3"><div><h3 className="text-xl font-bold">{version.data.version.title}</h3><p>{version.data.topics.length} topics · {version.data.version.publication_status||version.data.version.status}</p>{version.data.version.source_url?<a className="underline" href={version.data.version.source_url} target="_blank" rel="noopener noreferrer">Open official source ↗</a>:<p className="text-amber-800">Official source URL is required before review and publication.</p>}</div></div>
    {version.data.version.publication_status==='DRAFT'&&<details className="mt-4 rounded-xl border border-slate-200 p-4"><summary className="cursor-pointer font-bold">Add a topic missed by extraction</summary><div className="mt-3 grid gap-3 md:grid-cols-2"><label className={label}>Class<select className="admin-select" value={newTopic.gradeCode} onChange={event=>setNewTopic({...newTopic,gradeCode:event.target.value})}><option value="">Choose class</option>{options.data?.grades.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Subject<select className="admin-select" value={newTopic.subjectId} onChange={event=>setNewTopic({...newTopic,subjectId:event.target.value})}><option value="">Choose subject</option>{options.data?.subjects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={label}>Unit<input className="admin-input" value={newTopic.unit} onChange={event=>setNewTopic({...newTopic,unit:event.target.value})}/></label><label className={label}>Chapter<input className="admin-input" value={newTopic.chapter} onChange={event=>setNewTopic({...newTopic,chapter:event.target.value})}/></label><label className={label}>Topic<input className="admin-input" value={newTopic.topic} onChange={event=>setNewTopic({...newTopic,topic:event.target.value})}/></label><label className={label}>Hindi topic<input className="admin-input" value={newTopic.topicHi} onChange={event=>setNewTopic({...newTopic,topicHi:event.target.value})}/></label><label className={label}>Page reference<input className="admin-input" value={newTopic.pageReference} onChange={event=>setNewTopic({...newTopic,pageReference:event.target.value})} placeholder="Page 12"/></label><label className={label}>Order<input className="admin-input" type="number" min="0" value={newTopic.sortOrder} onChange={event=>setNewTopic({...newTopic,sortOrder:event.target.value})}/></label><label className={`${label} md:col-span-2`}>Learning outcome (optional)<textarea className="admin-textarea" value={newTopic.learningOutcome} onChange={event=>setNewTopic({...newTopic,learningOutcome:event.target.value})}/></label></div><button className="btn-primary mt-3" disabled={createTopic.isPending||!newTopic.gradeCode||!newTopic.subjectId||!newTopic.unit||!newTopic.chapter||!newTopic.topic||!newTopic.pageReference} onClick={()=>createTopic.mutate()}>{createTopic.isPending?'Adding…':'Add topic to Draft'}</button></details>}
    <div className="mt-4 max-h-[560px] space-y-3 overflow-auto rounded-xl border border-slate-200 p-3">{groupedTopics.map(([key,topics])=><details key={key} open><summary className="cursor-pointer font-bold text-slate-900">{key} <span className="font-normal text-slate-500">({topics.length})</span></summary><div className="mt-2 space-y-2">{topics.map(topic=><article key={topic.id} className={`rounded-lg border p-3 ${topic.is_retired?'bg-slate-100 opacity-70':'bg-white'}`}><div className="flex flex-wrap items-center justify-between gap-2"><div><strong>{topic.title}</strong>{topic.title_hi&&<span> / {topic.title_hi}</span>}<p className="text-xs text-slate-600">{topic.page_reference} · {topic.is_retired?'Retired':'Active'}</p></div><div className="flex gap-2">{version.data.version.publication_status==='DRAFT'&&<button className="btn-secondary" onClick={()=>setEditingTopic({...topic})}>Edit</button>}{version.data.version.publication_status==='DRAFT'&&<button className="btn-secondary" disabled={statusNote.trim().length<10||retire.isPending} onClick={()=>retire.mutate(topic)}>{topic.is_retired?'Restore':'Remove'}</button>}</div></div></article>)}</div></details>)}</div>
    {editingTopic&&<TopicEditor topic={editingTopic} setTopic={setEditingTopic} onCancel={()=>setEditingTopic(null)} onSave={()=>updateTopic.mutate(editingTopic)} saving={updateTopic.isPending}/>}
    <label className={`${label} mt-4`}>Review or correction note<textarea className="admin-textarea" value={statusNote} onChange={event=>setStatusNote(event.target.value)} placeholder="At least 10 characters"/></label><label className="mt-3 flex items-start gap-2 text-sm"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/><span>I verified board, year, medium, class, subject, unit, chapter, topic and page references against the official source.</span></label><div className="mt-4 flex flex-wrap gap-2"><button className="btn-secondary" disabled={!confirmed||!version.data.version.source_url||statusNote.trim().length<10||status.isPending} onClick={()=>status.mutate('REVIEWED')}>Mark reviewed</button><button className="btn-primary" disabled={!confirmed||statusNote.trim().length<10||status.isPending||version.data.version.publication_status!=='REVIEWED'} onClick={()=>status.mutate('ACTIVE')}>Publish to matching students</button><button className="btn-secondary" disabled={statusNote.trim().length<10||status.isPending} onClick={()=>status.mutate('DRAFT')}>Return to Draft</button><button className="btn-secondary" disabled={statusNote.trim().length<10||status.isPending} onClick={()=>status.mutate('ARCHIVED')}>Archive</button></div>
   </div>}
  </section>}
 </main>;
}

function DocumentPanel({doc,options,edit,setters,onClose,onSave,saving,onDelete,deleting,review,reviewSetters,onReview,reviewing,onOpenVersion}:{doc:SyllabusDocument;options?:{grades:{code:string;name:string}[];subjects:{id:string;name:string}[]};edit:{title:string;grade:string;subject:string;source:string;language:'en'|'hi'};setters:{title:(value:string)=>void;grade:(value:string)=>void;subject:(value:string)=>void;source:(value:string)=>void;language:(value:'en'|'hi')=>void};onClose:()=>void;onSave:()=>void;saving:boolean;onDelete:()=>void;deleting:boolean;review:{note:string;rights:boolean;evidence:string};reviewSetters:{note:(value:string)=>void;rights:(value:boolean)=>void;evidence:(value:string)=>void};onReview:(value:'APPROVED'|'REJECTED')=>void;reviewing:boolean;onOpenVersion:()=>void}){
 return <section className={panel}><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-bold">{doc.title}</h2><p className="text-sm text-slate-600">{doc.page_count} pages · {doc.status} · {doc.structured_outline?.length||doc.topic_count||0} extracted topics</p></div><button className="btn-secondary" onClick={onClose}>Close</button></div>
  {doc.downloadUrl&&<div className="mt-4 overflow-hidden rounded-xl border border-slate-200"><iframe title={`Preview ${doc.title}`} src={doc.downloadUrl} className="h-[520px] w-full bg-slate-50"/><a className="block p-3 text-center underline" href={doc.downloadUrl} target="_blank" rel="noopener noreferrer">Open PDF in a new tab ↗</a></div>}
  <div className="mt-5 grid gap-3 md:grid-cols-2"><label className={label}>Title<input className="admin-input" value={edit.title} onChange={event=>setters.title(event.target.value)}/></label><label className={label}>Class<select className="admin-select" value={edit.grade} onChange={event=>setters.grade(event.target.value)}><option value="">Choose class</option>{options?.grades.map(item=><option key={item.code} value={item.code}>{item.name}</option>)}</select></label><label className={label}>Subject<select className="admin-select" value={edit.subject} onChange={event=>setters.subject(event.target.value)}><option value="">Choose subject</option>{options?.subjects.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className={label}>Medium<select className="admin-select" value={edit.language} onChange={event=>setters.language(event.target.value as 'en'|'hi')}><option value="en">English</option><option value="hi">Hindi</option></select></label><label className={`${label} md:col-span-2`}>Official source URL<input className="admin-input" type="url" value={edit.source} onChange={event=>setters.source(event.target.value)} placeholder="Required before approval"/></label></div>
  {(doc.detected_grade_code||doc.detected_subject)&&<p className="mt-2 text-sm text-slate-600">Detected from PDF: {doc.detected_grade_code?.replace('CLASS_','Class ')||'class unknown'} · {doc.detected_subject||'subject unknown'}</p>}
  <div className="mt-3 flex flex-wrap gap-2"><button className="btn-primary" disabled={saving||!edit.title} onClick={onSave}>{saving?'Saving…':'Save details and rebuild Draft'}</button>{doc.version_id&&<button className="btn-secondary" onClick={onOpenVersion}>Review extracted syllabus tree →</button>}{doc.status!=='APPROVED'&&<button className="btn-secondary" disabled={deleting} onClick={onDelete}>{deleting?'Deleting…':'Delete incorrect Draft'}</button>}</div>
  <details className="mt-5"><summary className="cursor-pointer font-bold">View extracted structure ({doc.structured_outline?.length||0})</summary><div className="mt-3 max-h-80 overflow-auto rounded-lg bg-slate-50 p-3">{doc.structured_outline?.map((row,index)=><p className="border-b border-slate-200 py-2 text-sm" key={`${row.topic}-${index}`}><strong>{row.unit}</strong> › {row.chapter} › {row.topic} <span className="text-slate-500">({row.pageReference}, {row.confidence})</span></p>)}</div></details>
  <div className="mt-5 border-t border-slate-200 pt-4"><h3 className="font-bold">Document review</h3><p className="text-sm text-slate-600">Approving the evidence document does not publish its structured syllabus. Publication remains a separate action.</p><label className={`${label} mt-3`}>Review note<textarea className="admin-textarea" value={review.note} onChange={event=>reviewSetters.note(event.target.value)} placeholder="Describe what was verified"/></label><label className="mt-3 flex gap-2 text-sm"><input type="checkbox" checked={review.rights} onChange={event=>reviewSetters.rights(event.target.checked)}/>Allow students to download a copy after rights verification</label>{review.rights&&<label className={`${label} mt-2`}>Rights evidence URL<input className="admin-input" type="url" value={review.evidence} onChange={event=>reviewSetters.evidence(event.target.value)}/></label>}<div className="mt-3 flex gap-2"><button className="btn-primary" disabled={reviewing||review.note.trim().length<10||!edit.source} onClick={()=>onReview('APPROVED')}>Approve document</button><button className="btn-secondary" disabled={reviewing||review.note.trim().length<10} onClick={()=>onReview('REJECTED')}>Reject</button></div></div>
 </section>;
}
function TopicEditor({topic,setTopic,onCancel,onSave,saving}:{topic:SyllabusTopic;setTopic:(topic:SyllabusTopic)=>void;onCancel:()=>void;onSave:()=>void;saving:boolean}){return <div className="mt-4 rounded-xl border-2 border-orange-300 bg-orange-50 p-4"><h3 className="font-bold">Edit topic</h3><div className="mt-3 grid gap-3 md:grid-cols-2"><label className={label}>Unit<input className="admin-input" value={topic.unit||''} onChange={event=>setTopic({...topic,unit:event.target.value})}/></label><label className={label}>Chapter<input className="admin-input" value={topic.chapter} onChange={event=>setTopic({...topic,chapter:event.target.value})}/></label><label className={label}>Topic<input className="admin-input" value={topic.title} onChange={event=>setTopic({...topic,title:event.target.value})}/></label><label className={label}>Hindi topic<input className="admin-input" value={topic.title_hi||''} onChange={event=>setTopic({...topic,title_hi:event.target.value})}/></label><label className={label}>Page reference<input className="admin-input" value={topic.page_reference} onChange={event=>setTopic({...topic,page_reference:event.target.value})}/></label><label className={label}>Learning outcome<input className="admin-input" value={topic.learning_outcome||''} onChange={event=>setTopic({...topic,learning_outcome:event.target.value})}/></label></div><div className="mt-3 flex gap-2"><button className="btn-primary" disabled={saving||!topic.title||!topic.chapter||!topic.unit||!topic.page_reference} onClick={onSave}>{saving?'Saving…':'Save topic'}</button><button className="btn-secondary" onClick={onCancel}>Cancel</button></div></div>;}
